29	export function createWeightStores({
30	    dataDir,
31	    env,
32	    hfBaseUrl,
33	    inspect,
34	    download,
35	    remove,
36	    resolveHf,
37	    state,
38	    save,
39	    // The artifact of the job that is running now, or null.
40	    activeArtifact,
41	    downloadSnapshot = downloadSnapshotFile,
42	    inspectSnapshot = inspectSnapshotFile,
43	    resolveSnapshot = resolveHuggingFaceSnapshot,
44	}) {
45	    const ggufRoot = path.join(dataDir, 'models', 'gguf');
46	    const ollamaModels = path.join(dataDir, 'models', 'ollama');
47	    const hfRoot = path.join(dataDir, 'models', 'hf');
48	
49	    // One file, or every shard of a split GGUF (DS002), each as the downloader's artifact.
50	    const filesOf = (source) => (source.shards
51	        ? source.shards.map((shard) => ({ ...source, shards: undefined, file: shard.file, size: shard.size, sha256: shard.sha256 }))
52	        : [source]);
53	
54	    const huggingface = Object.freeze({
55	        type: 'huggingface',
56	        fetchedBy: 'controller',
57	        // A split GGUF is one artifact: its commit, first shard and shard count.
58	        key: (source) => `gguf:${source.repo}@${source.commit}/${source.file}${source.shards ? `#${source.shards.length}` : ''}`,
59	        isPinned: (source) => Boolean(source.commit) && (!splitGgufName(source.file) || Array.isArray(source.shards)),
60	        async state(source) {
61	            if (!huggingface.isPinned(source)) return { state: 'unpinned', bytes: 0, total: null };
62	            if (!source.shards) {
63	                const inspected = await inspect({ root: ggufRoot, artifact: source });
64	                return { ...inspected, total: source.size };
65	            }
66	            // The set is complete only when every shard is; bytes are counted over the set.
67	            const shards = [];
68	            for (const file of filesOf(source)) shards.push(await inspect({ root: ggufRoot, artifact: file }));
69	            const bytes = shards.reduce((sum, shard) => sum + (shard.bytes || 0), 0);
70	            const all = (value) => shards.every((shard) => shard.state === value);
71	            const stateOf = all('complete') ? 'complete' : all('absent') ? 'absent' : 'partial';
72	            return { state: stateOf, bytes, total: source.size, ...(source.shards ? { shards: shards.length } : {}) };
73	        },
74	        async fetch({ artifact, signal, onProgress }) {
75	            // Shard by shard into one directory; progress counts the whole set.
76	            let done = 0;
77	            let transferred = 0;
78	            let first = null;
79	            const files = [];
80	            for (const file of filesOf(artifact)) {
81	                const offset = done;
82	                const result = await download({
83	                    artifact: file,
84	                    root: ggufRoot,
85	                    token: env.HF_TOKEN || '',
86	                    baseUrl: hfBaseUrl,
87	                    onProgress: (progress) => onProgress?.({
88	                        ...progress,
89	                        bytes: offset + (progress.bytes || 0),
90	                        total: artifact.size,
91	                        transferred: transferred + (progress.transferred || 0),
92	                    }),
93	                    signal,
94	                });
95	                first ??= result.path;
96	                files.push(result.path);
97	                done += file.size;
98	                transferred += result.bytesTransferred || 0;
99	            }
100	            return { path: first, files, bytes: artifact.size, bytesTransferred: transferred };
101	        },
102	        async remove(source) {
103	            if (!source.commit) return 0;
104	            let freed = 0;
105	            for (const file of filesOf(source)) freed += await remove({ root: ggufRoot, artifact: file });
106	            return freed;
107	        },
108	        // Pinning reads Hugging Face metadata only; no weights are downloaded.
109	        async pin(source) {
110	            if (huggingface.isPinned(source)) return source;
111	            const resolve = (file, revision) => resolveHf({
112	                repo: source.repo,
113	                file,
114	                revision,
115	                token: env.HF_TOKEN || '',
116	                baseUrl: hfBaseUrl,
117	            });
118	            const resolved = await resolve(source.file, source.revision || 'main');
119	            const files = splitGgufFiles(source.file);
120	            if (!files) return { ...source, commit: resolved.commit, size: resolved.size, sha256: resolved.sha256 };
121	            // Every shard at the same commit.
122	            const shards = [{ file: source.file, size: resolved.size, sha256: resolved.sha256 }];
123	            for (const file of files.slice(1)) {
124	                const next = await resolve(file, resolved.commit);
125	                shards.push({ file, size: next.size, sha256: next.sha256 });
126	            }
127	            return { ...source, commit: resolved.commit, size: shards.reduce((sum, shard) => sum + shard.size, 0), shards };
128	        },
129	        // An update keeps the pinned commit while repository, file and
130	        // revision are unchanged; it never silently re-resolves a branch.
131	        carryPin(next, previous) {
132	            if (next.commit || previous?.type !== 'huggingface' || !previous.commit) return next;
133	            if (next.repo !== previous.repo || next.file !== previous.file || next.revision !== previous.revision) return next;
134	            return previous.shards
135	                ? { ...next, commit: previous.commit, size: previous.size, shards: previous.shards }
136	                : { ...next, commit: previous.commit, size: previous.size, sha256: previous.sha256 };
137	        },
138	        paths: (source) => artifactPaths({ root: ggufRoot, artifact: filesOf(source)[0] }),
139	    });
140	
141	    function manifestOrNull(tag) {
142	        try {
143	            return readOllamaManifest(ollamaModels, tag);
144	        } catch (error) {
145	            if (error?.code === 'invalid_manifest') return null;
146	            throw error;
147	        }
148	    }
149	
150	    function pulls() {
151	        const current = state();
152	        current.ollamaPulls ||= {};
153	        return current.ollamaPulls;
154	    }
155	
