163	            if (manifest?.complete) return { state: 'complete', bytes: manifest.size, total: manifest.size };
164	            const partial = partialPullBytes(ollamaModels, state().ollamaPulls?.[source.tag] || []);
165	            return { state: partial ? 'partial' : 'absent', bytes: partial, total: source.size ?? null };
166	        },
167	        // Ollama tags can share blobs: never remove a partial another tag's
168	        // pull claims, and refuse while another tag's running pull has
169	        // reported a blob this deletion would touch.
170	        async remove(source) {
171	            const recorded = pulls();
172	            const claimedByOthers = Object.entries(recorded)
173	                .filter(([tag]) => tag !== source.tag)
174	                .flatMap(([, digests]) => digests);
175	            const running = activeArtifact();
176	            const activeTag = running?.type === 'ollama' ? running.tag : null;
177	            if (activeTag && activeTag !== source.tag) {
178	                const touched = new Set([
179	                    ...(recorded[source.tag] || []),
180	                    ...(manifestOrNull(source.tag)?.blobs.map((blob) => blob.digest) || []),
181	                ]);
182	                if ((recorded[activeTag] || []).some((digest) => touched.has(digest))) {
183	                    throw new LocalLlmError('in_use', `The running ${activeTag} download uses some of these files; `
184	                        + 'wait for it to finish or cancel it first.');
185	                }
186	            }
187	            const freed = deleteOllamaModel(ollamaModels, source.tag)
188	                + deleteOllamaPartials(ollamaModels, {
189	                    digests: recorded[source.tag] || [],
190	                    claimedByOthers,
191	                    keepOrphans: activeTag !== null,
192	                });
193	            if (recorded[source.tag]) {
194	                delete recorded[source.tag];
195	                save();
196	            }
197	            return freed;
198	        },
199	        pin: async (source) => source,
200	        carryPin: (next) => next,
201	        // Used by the Ollama runner while it pulls.
202	        readManifest: (tag) => readOllamaManifest(ollamaModels, tag),
203	        recordPull(tag, digest) {
204	            const digests = pulls()[tag] ||= [];
205	            if (digests.includes(digest)) return;
206	            digests.push(digest);
207	            save();
208	        },
209	        clearPulls(tag) {
210	            const recorded = state().ollamaPulls;
211	            if (!recorded?.[tag]) return;
212	            delete recorded[tag];
213	            save();
214	        },
215	    });
216	
217	    const snapshotFile = (source, file) => ({
218	        repo: source.repo, commit: source.commit, file: file.path, size: file.size,
219	        ...(file.sha256 !== undefined ? { sha256: file.sha256 } : { gitOid: file.gitOid }),
220	    });
221	
222	    async function treeBytes(dir) {
223	        let total = 0;
224	        let entries = [];
225	        try { entries = await fs.promises.readdir(dir, { withFileTypes: true }); } catch { return 0; }
226	        for (const entry of entries) {
227	            const full = path.join(dir, entry.name);
228	            if (entry.isDirectory()) total += await treeBytes(full);
229	            else if (entry.isFile()) total += (await fs.promises.lstat(full)).size;
230	        }
231	        return total;
232	    }
233	
234	    const hfSnapshot = Object.freeze({
235	        type: 'hf-snapshot',
236	        fetchedBy: 'controller',
237	        key: (source) => `hf:${source.repo}@${source.commit}`,
238	        isPinned: (source) => Boolean(source.commit && source.files?.length),
239	        // Complete only when every file has verified; a partial snapshot is never ready.
240	        async state(source) {
241	            if (!source.commit || !source.files) return { state: 'unpinned', bytes: 0, total: null };
242	            let bytes = 0;
243	            let complete = true;
244	            let partial = false;
245	            for (const file of source.files) {
246	                const inspected = await inspectSnapshot({ root: hfRoot, artifact: snapshotFile(source, file) });
247	                bytes += inspected.bytes;
248	                if (inspected.state !== 'complete') complete = false;
249	                if (inspected.state !== 'absent') partial = true;
250	            }
251	            return { state: complete ? 'complete' : (partial ? 'partial' : 'absent'), bytes, total: source.size };
252	        },
253	        async fetch({ artifact: source, signal, onProgress = () => {} }) {
254	            let done = 0;
255	            let transferred = 0;
256	            for (const file of source.files) {
257	                const result = await downloadSnapshot({
258	                    root: hfRoot,
259	                    artifact: snapshotFile(source, file),
260	                    token: env.HF_TOKEN || '',
261	                    baseUrl: hfBaseUrl,
262	                    signal,
263	                    onProgress: (progress) => onProgress({
264	                        ...progress,
265	                        bytes: done + progress.bytes,
266	                        total: source.size,
267	                        transferred: transferred + (progress.transferred ?? 0),
268	                    }),
269	                });
270	                done += file.size;
271	                transferred += result.bytesTransferred;
272	                onProgress({ bytes: done, total: source.size, transferred, rate: 0, etaSeconds: null });
273	            }
274	            const { dir } = snapshotPaths({ root: hfRoot, repo: source.repo, commit: source.commit });
275	            return { path: dir, bytes: source.size, bytesTransferred: transferred };
276	        },
277	        // Delete weights removes the whole snapshot and its bookkeeping.
278	        async remove(source) {
279	            if (!source.commit) return 0;
280	            const { dir, stateDir } = snapshotPaths({ root: hfRoot, repo: source.repo, commit: source.commit });
281	            const freed = await treeBytes(dir) + await treeBytes(stateDir);
282	            await fs.promises.rm(dir, { recursive: true, force: true });
283	            await fs.promises.rm(stateDir, { recursive: true, force: true });
284	            return freed;
285	        },
286	        // Pinning reads Hugging Face metadata only; no weights are downloaded.
287	        async pin(source) {
288	            if (source.commit && source.files) return source;
289	            const resolved = await resolveSnapshot({
290	                repo: source.repo,
291	                revision: source.revision || 'main',
292	                token: env.HF_TOKEN || '',
293	                baseUrl: hfBaseUrl,
294	            });
295	            const files = resolved.files.map((file) => ({ ...file }));
296	            return { ...source, commit: resolved.commit, files, size: files.reduce((sum, file) => sum + file.size, 0) };
297	        },
298	        // An update keeps the pin while repository and revision are unchanged.
299	        carryPin(next, previous) {
300	            if (next.commit || previous?.type !== 'hf-snapshot' || !previous.commit) return next;
301	            if (next.repo !== previous.repo || next.revision !== previous.revision) return next;
302	            return { ...next, commit: previous.commit, files: previous.files, size: previous.size };
303	        },
304	    });
305	
306	    return Object.freeze({ huggingface, ollama, 'hf-snapshot': hfSnapshot });
307	}
